const axios = require('axios');
const cheerio = require('cheerio');

module.exports = {
    category: 'Search',
    params: ['q'],
    desc: 'Myinstants Sound Search',

    async run(req, res) {
        const q = String(req.query.q || req.body.q || '').trim();

        if (!q) {
            return res.status(400).json({ creator: 'Nanzz', status: false, message: 'Parameter q diperlukan' });
        }

        try {
            const response = await axios.get(`https://www.myinstants.com/en/search/`, {
                params: { name: q },
                headers: {
                    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0.0.0 Safari/537.36',
                    'Accept': 'text/html'
                }
            });

            const $ = cheerio.load(response.data);
            const sounds = [];

            $('.instant').each((_, el) => {
                const button = $(el).find('button.small-button');
                const onclick = button.attr('onclick') || '';
                const title = $(el).find('.instant-link').text().trim();
                const url = $(el).find('.instant-link').attr('href');

                const mp3Match = onclick.match(/play\('([^']+\.mp3)'/);
                if (mp3Match) {
                    sounds.push({
                        title,
                        audio: `https://www.myinstants.com${mp3Match[1]}`,
                        url: url ? `https://www.myinstants.com${url}` : null
                    });
                }
            });

            return res.json({
                creator: 'Nanzz',
                status: true,
                result: {
                    query: q,
                    total: sounds.length,
                    sounds
                }
            });

        } catch (err) {
            return res.status(500).json({ creator: 'Nanzz', status: false, message: err.message });
        }
    }
};

if (require.main === module) {
    const q = process.argv[2];
    if (!q) { console.log('Usage: node myinstants.js <query>'); process.exit(1); }
    module.exports.run(
        { query: { q }, body: {} },
        { status: () => ({ json: d => console.log('\n' + JSON.stringify(d, null, 2)) }), json: d => console.log('\n' + JSON.stringify(d, null, 2)) }
    );
}

